insert into public.vehicle_specs (key, year, make, model, engine, specs)
select key, year, make, model, engine,
  (select jsonb_object_agg(field, jsonb_build_object(
      'value', entry->>0,
      'source', case when entry->>1 = '' then book else book || ', p. ' || (entry->>1) end,
      'sourceUrl', url,
      'by', 'Shop library seed',
      'at', now()))
   from jsonb_each(specs) as item(field, entry))
from seed
on conflict (key) do update
  set specs = excluded.specs || public.vehicle_specs.specs,
      updated_at = now();
